            ctx.contentType("text/csv; charset=utf-8");
            ctx.result(csv);

        } catch (DateTimeParseException e) {
            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
        }
    }
}

