import com.pousada.config.Database;
import com.pousada.repository.MessageRepository;
import com.pousada.repository.ReservationRepository;
import com.pousada.repository.RoomRepository;
import com.pousada.service.MessageService;
import com.pousada.service.ReportService;
import com.pousada.service.ReservationService;
import com.pousada.service.RoomService;
import com.pousada.service.messaging.*;
import io.javalin.Javalin;
import io.javalin.json.JavalinJackson;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

@Testcontainers
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class IntegrationTest {

    @Container
    private static final PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18")
        .withDatabaseName("test")
        .withUsername("test")
        .withPassword("test");

    private Javalin app;
    private Database database;

    @BeforeAll
    public void setup() {
        postgres.start();

        database = new Database(postgres.getJdbcUrl(), postgres.getUsername(), postgres.getPassword());

        RoomRepository roomRepository = new RoomRepository(database);
        ReservationRepository reservationRepository = new ReservationRepository(database);
        MessageRepository messageRepository = new MessageRepository(database);

        List<MessageRule> rules = new ArrayList<>();
        rules.add(new EmailValidationRule());
        rules.add(new ArchiveCopyRule());
        MessageProcessor messageProcessor = new MessageProcessor(rules);

        MessageService messageService = new MessageService(messageRepository, messageProcessor);
        RoomService roomService = new RoomService(roomRepository);
        ReservationService reservationService = new ReservationService(
            reservationRepository, roomRepository, messageService
        );
        ReportService reportService = new ReportService(reservationRepository, roomRepository);

        RoomController roomController = new RoomController(roomService);
        ReservationController reservationController = new ReservationController(reservationService);
        MessageController messageController = new MessageController(messageService);
        ReportController reportController = new ReportController(reportService);

        ObjectMapper objectMapper = new ObjectMapper();
        objectMapper.registerModule(new JavaTimeModule());
        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

        app = Javalin.create(config -> {
            config.jsonMapper(new JavalinJackson(objectMapper));
        }).start(7000);

        app.get("/rooms", roomController::getRooms);
        app.post("/reservations", reservationController::createReservation);
        app.get("/reservations/{id}", reservationController::getReservation);
        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
        app.post("/reservations/{id}/check-in", reservationController::checkInReservation);
        app.post("/reservations/{id}/check-out", reservationController::checkOutReservation);
        app.get("/reservations/{id}/document", reservationController::getDocument);
        app.get("/messages", messageController::getMessages);
        app.get("/reports/occupancy", reportController::getOccupancyReport);
        app.get("/reports/revenue", reportController::getRevenueReport);

        RestAssured.baseURI = "http://localhost";
        RestAssured.port = 7000;
    }

    @AfterAll
    public void tearDown() {
        if (app != null) {
            app.stop();
        }
        if (database != null) {
            database.close();
        }
    }

    @Test
    public void shouldGetAllRooms() {
        given()
            .when()
            .get("/rooms")
            .then()
            .statusCode(200)
            .body("size()", is(5))
            .body("[0].number", is("101"))
            .body("[0].type", is("STANDARD"))
            .body("[0].capacity", is(2))
            .body("[0].nightlyRate", is(249.90f));
    }

    @Test
    public void shouldCreateAndConfirmReservation() {
        Map<String, Object> request = Map.of(
            "roomNumber", "101",
            "guestName", "João Silva",
            "guestEmail", "joao@example.com",
            "guestCpf", "12345678901",
            "checkIn", "2027-03-10",
            "checkOut", "2027-03-12",
            "guests", 2,
            "ratePlan", "STANDARD"
        );

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("roomNumber", is("101"))
            .body("guestName", is("João Silva"))
            .body("status", is("PENDING"))
            .body("nights", is(2))
            .body("subtotal", is(499.80f))
            .body("discount", is(0.00f))
            .body("total", is(499.80f))
            .body("amountPaid", is(0.00f))
            .extract()
            .path("id");

        given()
            .when()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200)
            .body("status", is("CONFIRMED"))
            .body("amountPaid", is(499.80f));

        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("size()", is(2))
            .body("[0].to", is("joao@example.com"))
            .body("[0].status", is("SENT"))
            .body("[0].subject", is("Reserva confirmada - Pousada Maré Alta"))
            .body("[1].to", is("arquivo@pousadamarealta.com.br"))
            .body("[1].status", is("SENT"))
            .body("[1].subject", is("[Cópia] Reserva confirmada - Pousada Maré Alta"));
    }

    @Test
    public void shouldBlockInvalidEmail() {
        Map<String, Object> request = Map.of(
            "roomNumber", "102",
            "guestName", "Maria Santos",
            "guestEmail", "maria@invalid",
            "guestCpf", "98765432109",
            "checkIn", "2027-04-10",
            "checkOut", "2027-04-12",
            "guests", 1,
            "ratePlan", "STANDARD"
        );

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .when()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("find { it.to == 'maria@invalid' }.status", is("BLOCKED"));
    }

    @Test
    public void shouldCalculateHighSeasonPricing() {
        Map<String, Object> request = Map.of(
            "roomNumber", "201",
            "guestName", "Carlos Dias",
            "guestEmail", "carlos@example.com",
            "guestCpf", "11122233344",
            "checkIn", "2027-07-10",
            "checkOut", "2027-07-12",
            "guests", 2,
            "ratePlan", "STANDARD"
        );

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("nights", is(2))
            .body("subtotal", is(935.76f))
            .body("total", is(935.76f));
    }

    @Test
    public void shouldApplyNonRefundableDiscount() {
        Map<String, Object> request = Map.of(
            "roomNumber", "301",
            "guestName", "Ana Costa",
            "guestEmail", "ana@example.com",
            "guestCpf", "55566677788",
            "checkIn", "2027-05-01",
            "checkOut", "2027-05-03",
            "guests", 2,
            "ratePlan", "NON_REFUNDABLE"
        );

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("nights", is(2))
            .body("subtotal", is(1159.80f))
            .body("discount", is(173.97f))
            .body("total", is(985.83f));
