    @Test
    public void shouldPreventDoubleBooking() {
        Map<String, Object> request1 = Map.of(
            "roomNumber", "202",
            "guestName", "Paulo Lima",
            "guestEmail", "paulo@example.com",
            "guestCpf", "99988877766",
            "checkIn", "2027-06-10",
            "checkOut", "2027-06-15",
            "guests", 2,
            "ratePlan", "STANDARD"
        );

        given()
            .contentType(ContentType.JSON)
            .body(request1)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201);

        Map<String, Object> request2 = Map.of(
            "roomNumber", "202",
            "guestName", "Fernanda Rocha",
            "guestEmail", "fernanda@example.com",
            "guestCpf", "44455566677",
            "checkIn", "2027-06-12",
            "checkOut", "2027-06-17",
            "guests", 1,
            "ratePlan", "STANDARD"
        );

        given()
            .contentType(ContentType.JSON)
            .body(request2)
            .when()
            .post("/reservations")
            .then()
            .statusCode(409)
            .body("error", is("ROOM_UNAVAILABLE"));
    }

    @Test
    public void shouldGenerateOccupancyReport() {
        Map<String, Object> request = Map.of(
            "roomNumber", "101",
            "guestName", "Roberto Alves",
            "guestEmail", "roberto@example.com",
            "guestCpf", "12312312312",
            "checkIn", "2027-08-01",
            "checkOut", "2027-08-03",
            "guests", 1,
            "ratePlan", "STANDARD"
        );

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .when()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        String csv = given()
            .queryParam("date", "2027-08-01")
            .when()
            .get("/reports/occupancy")
            .then()
            .statusCode(200)
            .contentType("text/csv; charset=utf-8")
            .extract()
            .asString();

        Assertions.assertTrue(csv.contains("room,type,reservation,check_in,check_out"));
        Assertions.assertTrue(csv.contains("101,STANDARD," + reservationId + ",2027-08-01,2027-08-03"));
        Assertions.assertTrue(csv.contains("total,1/5"));
    }

    @Test
    public void shouldGenerateRevenueReport() {
        Map<String, Object> request = Map.of(
            "roomNumber", "201",
            "guestName", "Lucia Martins",
            "guestEmail", "lucia@example.com",
            "guestCpf", "65465465465",
            "checkIn", "2027-09-15",
            "checkOut", "2027-09-17",
            "guests", 2,
            "ratePlan", "STANDARD"
        );

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .when()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        String csv = given()
            .queryParam("month", "2027-09")
            .when()
            .get("/reports/revenue")
            .then()
            .statusCode(200)
            .contentType("text/csv; charset=utf-8")
            .extract()
            .asString();

        Assertions.assertTrue(csv.contains("reservation,room,check_in,check_out,status,amount"));
        Assertions.assertTrue(csv.contains("201,2027-09-15,2027-09-17,CONFIRMED"));
        Assertions.assertTrue(csv.contains("total,"));
    }
}

